// No hand-written file over about 15,000 tokens (60 KB): a person or a model with a small context window can read any file whole and
// still have room to work. Data files, generated files and third-party files are listed below with the reason they may be bigger.
// Run by `npm test`; prints each file over the limit and exits 1.
import { execFileSync } from "node:child_process";
import { statSync } from "node:fs";
import { resolve } from "node:path";

const ROOT = resolve(import.meta.dirname, "..");
const LIMIT = 60_000; // bytes; about 15,000 tokens at four bytes a token
const BINARY = /\.(png|jpe?g|gif|ico|svg|docx|xlsx|odt|rtf|pdf|zip|gz|woff2?|ttf|otf|wasm|dic|aff)$/i;

/** Files that may be bigger, each with its reason. */
const EXEMPT = {
  "package-lock.json": "generated by npm",
  "web/public/licenses.txt": "generated by npm run notices: the licence texts of everything the app ships",
  "web/src/languages/es.json": "data: the Spanish translation, one entry per interface string",
  "locales/source.json": "generated by npm run messages: every interface string, for translators",
  "web/src/csl/chicago-notes-bibliography.csl": "third-party data: the Citation Style Language style, kept as published",
  "packages/editor/src/thesaurus/english-data.ts": "data: the built-in English thesaurus",
  "packages/editor/src/pdf/brotli-data.ts": "data: the Brotli dictionary the PDF writer's fonts need",
  "crates/docxtor-core/tests/data/op_shapes.jsonl": "test data: one line per op shape",
  "perf/history.jsonl": "a log: one line per performance run",
  "crates/docxtor-core/src/ops.rs": "one item: the Op enum, every edit Docxtor can make, used across the crate; splitting it would change every call site and the op JSON (its helpers are in ops/)",
};

const files = execFileSync("git", ["ls-files", "-z"], { cwd: ROOT, encoding: "utf8" }).split("\0").filter(Boolean);
const over = [];
for (const f of files) {
  if (BINARY.test(f) || f in EXEMPT) continue;
  let size;
  try {
    size = statSync(resolve(ROOT, f)).size;
  } catch {
    continue; // deleted in the working tree
  }
  if (size > LIMIT) over.push([f, size]);
}
over.sort((a, b) => b[1] - a[1]);
if (over.length) {
  console.error(`${over.length} file(s) over ${LIMIT / 1000} KB (about ${LIMIT / 4000}k tokens). Split them by topic into files beside them:`);
  for (const [f, size] of over) console.error(`  ${f}  ${Math.round(size / 1000)} KB, about ${Math.round(size / 4000)}k tokens`);
  process.exit(1);
}
console.log(`File sizes: none over ${LIMIT / 1000} KB besides ${Object.keys(EXEMPT).length} data or generated files.`);
